new='''                    // CPython's `sum` is three loops, not one: an exact-int
                    // loop on a C long, a float loop on a C double, and the
                    // generic `PyNumber_Add` loop for everything else. The
                    // float loop is where the two CPython versions this tree
                    // targets disagree. 3.12+ (`builtin_sum_impl`) runs
                    // Neumaier compensated summation there — it keeps the naive
                    // running sum `f` and a correction `c`, and adds `c` once
                    // at the end, or when leaving the loop. 3.11 has no `c`.
                    // So `sum([0.1] * 10)` is `1.0` on 3.14 and
                    // `0.9999999999999999` on 3.11, and a naive fold here
                    // matched 3.11 silently: a MISMATCH against the reference,
                    // and a wrong answer for whichever interpreter the caller
                    // meant.
                    //
                    // The engine may only answer where both agree, so the loop
                    // carries both: `f` is the naive sum (bit-for-bit what
                    // 3.11 returns, and what 3.12+ holds before the
                    // correction), `c` is the correction only 3.12+ adds. If
                    // `f + c` and `f` are not the same bits, refuse. When they
                    // are, the answer is what every CPython prints. Nothing is
                    // widened by this: ints never enter the float loop except
                    // as `(double)value` added naively, which both versions do.
                    //
                    // Which loop CPython is in is tracked explicitly rather
                    // than read off `acc`'s type, because the transitions are
                    // one-way and depend on the *start*, not the running
                    // value: only an exact `int` start begins in the int loop,
                    // only leaving it on a float enters the float loop, and a
                    // `bool` start (`sum(xs, True)`) is generic from the first
                    // element — naive, and answered naively, on every version.
                    let mut iter = it.make_iter(v.clone())?;
                    let mut acc = start;
                    let mut int_loop = matches!(acc, Value::Int(_));
                    // `Some((f, c))` while CPython would be in its float loop.
                    let mut float_loop = match acc {
                        Value::Float(f) => Some((f, 0.0f64)),
                        _ => None,
                    };
                    while let Some(x) = it.iter_next(&mut iter)? {
                        if let Some((f, c)) = float_loop.as_mut() {
                            match x {
                                Value::Float(x) => {
                                    let t = *f + x;
                                    if f.abs() >= x.abs() {
                                        *c += (*f - t) + x;
                                    } else {
                                        *c += (x - t) + *f;
                                    }
                                    *f = t;
