        Ok(f)
    } else {
        Err(unsupported(
            "float-sum",
            "sum() over floats where CPython 3.11, 3.12 and 3.14 round differently (3.12+ compensates floats, 3.14 compensates ints in the float loop too); the answers differ",
        ))
    }
}
''')
