import re, sys
def patch(path, pairs):
    s = open(path).read()
    for old, new in pairs:
        n = s.count(old)
        assert n == 1, "%s: expected 1 match, got %d for:\n%s" % (path, n, old[:200])
        s = s.replace(old, new)
    open(path, 'w').write(s)
    print("patched", path, len(pairs))

