# DictWriter
def DW(rows, fields, header=True, **kw):
    o=io.StringIO(); w=csv.DictWriter(o, fields, **kw)
    r0 = w.writeheader() if header else None
    for row in rows: w.writerow(row)
    return (o.getvalue(), r0)
