def run(binpath, prog, stdin=b''):
    with tempfile.TemporaryDirectory() as td:
        p = subprocess.run([binpath, '-c', prog], cwd=td, input=stdin,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120)
    return p.returncode, p.stdout, p.stderr
def check(prog, stdin=b'', engine='l'):
    b = L if engine=='l' else CORE
    name = 'lypning-l' if engine=='l' else 'lypning'
    rc1,o1,e1 = run(b, prog, stdin)
    rc2,o2,e2 = run(PY3, prog, stdin)
    v=[]
    if rc1 == 90:
        if o1 != b'': v.append('CONTRACT: stdout before exit 90: %r' % o1[:200])
        lines = e1.decode('utf-8','replace').rstrip('\n').split('\n')
        if e1 == b'': v.append('CONTRACT: empty stderr on exit 90')
        elif len(lines) != 1: v.append('CONTRACT: %d stderr lines' % len(lines))
        elif not lines[0].startswith(name + ': unsupported: '): v.append('CONTRACT: malformed refusal')
        elif ': ' not in lines[0][len(name+': unsupported: '):]: v.append('CONTRACT: no KIND: DETAIL')
    else:
        if rc1 != rc2: v.append('EXIT %d vs cpython %d' % (rc1, rc2))
        if o1 != o2: v.append('STDOUT DIFF')
    if b'panicked' in e1 or rc1 in (101,134,139): v.append('PANIC rc=%d' % rc1)
    return v,(rc1,o1,e1),(rc2,o2,e2)
